/**
 * Measures an AnyPS5 source tree the way the project itself measures it.
 *
 * THE RULE THIS FILE EXISTS FOR: **no metric is invented here.** AnyPS5 publishes
 * its implementation statistics from `tools/progress.py`
 * (`GET https://boykopovar.github.io/AnyPS5/progress.json`, regenerated by CI on
 * every push that touches `core/libs/prx` or the RDNA opcode enum). Every number
 * the bot reports comes from one of exactly two places:
 *
 *   1. **that published snapshot**, for the headline counts and percentages;
 *   2. **this port of the same scanner**, run against the exact commit the
 *      published snapshot describes, when the caller needs *per-function* detail
 *      (which functions a pull request implemented, how far one library has come)
 *      that the snapshot only carries as name lists.
 *
 * Keeping the published file authoritative is deliberate: a scanner reimplemented
 * from the algorithm alone could silently disagree with the project's own badge,
 * and a bot that disagrees with the project's homepage about the project's
 * progress is worse than one that reports a slightly stale number.
 *
 * The statements below mirror `progress.py` one for one:
 *
 * - a function is **declared** when its body matches `APS5_VABI <name>(`;
 * - it is **todo** when its body reaches `NotImplemented_nid_no_patch`, directly
 *   or through an in-file helper;
 * - otherwise it is **done**, and additionally **inert** when every statement in
 *   its body is a bare `return;`, a constant/string return, a throw, or a call to
 *   a wrapper that is itself inert.
 */

/** Directory under the repository root that holds the reimplemented libraries. */
export const PRX_DIRECTORY = "core/libs/prx";
/** The RDNA opcode enum the shader statistic is derived from. */
export const OPCODE_HEADER =
  "core/shader/recompiler/RdnaDecoder/include/RdnaDecoder/RdnaOpcode.hpp";
/** Public base URL of the project's CI-generated progress page. */
export const PROGRESS_SITE = "https://boykopovar.github.io/AnyPS5";

/** One library (`core/libs/prx/libSce*`) as `progress.py` reports it. */
export interface LibraryGroup {
  /** Directory name, e.g. `libSceAc3Enc`. */
  readonly name: string;
  /** Display label (`name` without its `libSce` prefix). */
  readonly label: string;
  readonly done: number;
  readonly todo: number;
  readonly doneNames: readonly string[];
  readonly todoNames: readonly string[];
  readonly inertNames: readonly string[];
  /** Set when the directory holds no sources of its own but reuses another's. */
  readonly sharedSources: string | null;
}

/** One source file handed to the scanner. */
export interface SourceFile {
  /** Path relative to the repository root. */
  readonly path: string;
  readonly text: string;
}

const DEFINITION = /\bAPS5_VABI\s+(\w+)\s*\([^;{]*\)\s*(?:noexcept\s*)?(?:try\s*)?\{/g;
const STUB = "NotImplemented_nid_no_patch";
const CALL = /\b(\w+)\s*\(/g;
const KEYWORDS = "return|else|do|throw|co_return|co_await|co_yield|and|or|not|xor|bitand|bitor|compl";
const QUALIFIED = new RegExp(`(?:\\.|->|(?:\\b(?!(?:${KEYWORDS})\\b)\\w+|>)\\s*::)\\s*$`);
const STUB_WRAPPER =
  /^[ \t]*(?:static\s+)?(?:\[\[noreturn\]\]\s+)?(?:(?!APS5_VABI)[\w:<>,\s*&])+?[\s*&](?!(?:if|while|for|switch|catch|return|else)\b)(\w+)\s*\([^;{]*\)\s*(?:const\s*)?(?:noexcept\s*)?(?:->\s*[\w:<>*&\s]+?)?\{/gm;
const DISCARD = /\(void\)\s*\w+\s*;/;
const EMPTY_RETURN = /return\s*;/;
const CONST_RETURN =
  /return\s+(?:[+-]?\s*(?:0[xX][0-9a-fA-F]+|\d+)[uUlL]*|\w+|"(?:\.|[^"\\])*")\s*;/;
const WRAPPER_RETURN = /return\s+(\w+)\s*\(([^()]*)\)\s*;/;
const BARE_THROW = /throw\b[^;]*;/;

/** The tokenizer `progress.py` uses to blank comments and collapse literals. */
const CPP_TOKEN =
  /(?<comment>\/\/[^\n]*|\/\*[\s\S]*?\*\/)|(?<raw>(?:u8|u|U|L)?R"(?<delimiter>[^\s()\\]{0,16})\([\s\S]*?\)\k<delimiter>")|(?<string>(?:u8|u|U|L)?"(?:\\[\s\S]|[^"\\])*")|(?<char>(?:u8|u|U|L)?'(?:\\[\s\S]|[^'\\])*')|(?<code>(?:[0-9]|\.[0-9])[A-Za-z0-9_.']*|[A-Za-z_][A-Za-z0-9_]*|\S)/g;

/**
 * @returns the source with comments blanked and literals collapsed, exactly as
 * `progress.py`'s `code()` does.
 *
 * Comments keep their newlines (so an offset still lines up for a human reading
 * the file) and are otherwise spaces; every literal becomes `LITERAL`, which is
 * what stops a stub's name inside a string from being counted as a call.
 */
export function toScanText(source: string): string {
  const joined = source.replace(/\\\n/g, "").replace(/\\\r\n/g, "");
  return joined.replace(CPP_TOKEN, (match: string, ...rest: unknown[]) => {
    const groups = rest.at(-1) as Record<string, string | undefined>;
    if (groups.code !== undefined) {
      return match;
    }
    return groups.comment === undefined ? "LITERAL" : match.replace(/[^\n]/g, " ");
  });
}

/** @returns the index of the brace that closes the body opened at `start`. */
export function bodyEnd(text: string, start: number): number {
  let depth = 0;
  for (let i = start; i < text.length; i += 1) {
    const character = text[i];
    if (character === "{") {
      depth += 1;
    } else if (character === "}") {
      depth -= 1;
      if (depth === 0) {
        return i;
      }
    }
  }
  return text.length;
}


/**
 * Scans one library directory's sources into the counters `progress.py` keeps.
 *
 * @param sources sources of that directory, relative to the *directory*. Files
 * under a `tests` path are skipped, as upstream does, because a test that stubs a
 * function to exercise it is not that function's implementation.
 */
export function scanLibrary(name: string, sources: readonly SourceFile[]): LibraryGroup {
  const done = new Set<string>();
  const todo = new Set<string>();
  const inert = new Set<string>();
  const live = new Set<string>();

  for (const { path, text: raw } of sources) {
    if (path.split("/").includes("tests")) {
      continue;
    }
    const text = toScanText(raw);
    const calls = stubCalls(text);
    const wrappers = inertWrappers(text);

    for (const match of text.matchAll(DEFINITION)) {
      const functionName = match[1];
      if (functionName === undefined) {
        continue;
      }
      if (functionName.endsWith("_nid_no_patch") || functionName.endsWith("_nid_no_patch_cut")) {
        continue;
      }
      const open = (match.index ?? 0) + match[0].length - 1;
      const body = text.slice(open, bodyEnd(text, open));
      if (isStubBody(body, calls)) {
        todo.add(functionName);
        continue;
      }
      done.add(functionName);
      (isInertBody(body, wrappers) ? inert : live).add(functionName);
    }
  }

  for (const name of done) {
    todo.delete(name);
  }
  for (const name of live) {
    inert.delete(name);
  }

  return {
    name,
    label: name.startsWith("libSce") ? name.slice("libSce".length) : name,
    done: done.size,
    todo: todo.size,
    doneNames: [...done].sort(),
    todoNames: [...todo].sort(),
    inertNames: [...inert].sort(),
    sharedSources: null,
  };
}

/** @returns whether a body reaches the not-implemented stub, directly or via a helper. */
function isStubBody(body: string, calls: ReadonlySet<string>): boolean {
  for (const call of body.matchAll(CALL)) {
    const name = call[1];
    if (name === undefined || !calls.has(name)) {
      continue;
    }
    // A qualified call (`other::Stub()`) is a different function that happens to
    // share a name, which is why upstream tests the text before the call.
    if (!QUALIFIED.test(body.slice(0, call.index))) {
      return true;
    }
  }
  return false;
}


/**
 * @returns every in-file helper that transitively reaches the stub.
 *
 * A library commonly has a handful of `Fail()`-style helpers that all call
 * `NotImplemented_nid_no_patch`, and counting only direct calls would report every
 * export that uses them as implemented. This closes the transitive closure the way
 * `progress.py`'s `stub_calls()` does.
 */
export function stubCalls(text: string): ReadonlySet<string> {
  const helpers = new Map<string, Set<string>>();
  for (const match of text.matchAll(STUB_WRAPPER)) {
    const name = match[1];
    if (name === undefined) {
      continue;
    }
    const open = (match.index ?? 0) + match[0].length - 1;
    const targets = helpers.get(name) ?? new Set<string>();
    for (const call of text.slice(open, bodyEnd(text, open)).matchAll(CALL)) {
      if (call[1] !== undefined) {
        targets.add(call[1]);
      }
    }
    helpers.set(name, targets);
  }

  const calls = new Set<string>([STUB]);
  for (;;) {
    const found = [...helpers].filter(
      ([name, targets]) => !calls.has(name) && [...targets].some((target) => calls.has(target)),
    );
    if (found.length === 0) {
      return calls;
    }
    for (const [name] of found) {
      calls.add(name);
    }
  }
}

/**
 * @returns the helper names whose body is behaviourally empty.
 *
 * Grown from the empty set until stable, so a wrapper that only calls another
 * inert wrapper is itself inert: `return Forwarded(x);` where `Forwarded` is
 * `return 0;` is a function that compiles, reports success and does nothing —
 * which is exactly what the statistic exists to expose.
 */
export function inertWrappers(text: string): ReadonlySet<string> {
  const bodies = new Map<string, string>();
  for (const match of text.matchAll(STUB_WRAPPER)) {
    const name = match[1];
    if (name === undefined || bodies.has(name)) {
      continue;
    }
    const open = (match.index ?? 0) + match[0].length - 1;
    bodies.set(name, text.slice(open, bodyEnd(text, open)));
  }

  const names = new Set<string>();
  for (;;) {
    const found = [...bodies].filter(
      ([name, body]) => !names.has(name) && isInertBody(body, names),
    );
    if (found.length === 0) {
      return names;
    }
    for (const [name] of found) {
      names.add(name);
    }
  }
}

/**
 * @returns whether every statement of a body is inert.
 *
 * `(void)x;` is ignored wherever it appears (it is how upstream silences an unused
 * parameter); every other statement must be inert, and at most one may be a
 * terminal (`return`/`throw`) — `return 0; return 1;` is not inert, because the
 * second statement cannot be reached and the first is a lie.
 */
function isInertBody(body: string, wrappers: ReadonlySet<string>): boolean {
  let terminals = 0;
  for (const raw of statements(body)) {
    const statement = raw.trim();
    if (statement === "") {
      continue;
    }
    if (DISCARD.exec(statement)?.[0] === statement) {
      continue;
    }
    if (terminals > 0 || !isInertStatement(statement, wrappers)) {
      return false;
    }
    terminals += 1;
  }
  return true;
}

/** @returns whether one whole statement is a constant exit, or a call to an inert wrapper. */
function isInertStatement(statement: string, wrappers: ReadonlySet<string>): boolean {
  if (
    matchesWhole(EMPTY_RETURN, statement) ||
    matchesWhole(CONST_RETURN, statement) ||
    matchesWhole(BARE_THROW, statement)
  ) {
    return true;
  }
  const call = WRAPPER_RETURN.exec(statement);
  return call !== null && call[0] === statement && wrappers.has(call[1] ?? "");
}

/** @returns whether `pattern` matches the whole of `text`, not merely a prefix. */
function matchesWhole(pattern: RegExp, text: string): boolean {
  return pattern.exec(text)?.[0] === text;
}

/** Splits a braced body on its top-level semicolons, like `progress.py`. */
function statements(body: string): string[] {
  let depth = 0;
  let start = 1;
  const parts: string[] = [];
  for (let i = 1; i < body.length; i += 1) {
    const character = body[i];
    if (character === "{") {
      depth += 1;
    } else if (character === "}") {
      depth -= 1;
    } else if (character === ";" && depth === 0) {
      parts.push(body.slice(start, i + 1));
      start = i + 1;
    }
  }
  parts.push(body.slice(start));
  return parts;
}

